#[path="../src/vmedia_abi.rs"] mod vmedia_abi;
#[path="../src/encoder_abi.rs"] mod encoder_abi;
#[path="../src/encoder_state.rs"] mod encoder_state;
use encoder_abi::EncoderRequestError;
use encoder_state::{EncoderSlot,EncoderOwner,EncoderPoolRanges,EncoderPendingPacket,EncoderQueueConfig,PoolRangeError,MAX_ENCODER_POOL_RANGES,V4L2_ENCODER_OUTPUT_MPLANE,V4L2_ENCODER_CAPTURE_MPLANE,EncoderStateError as StateErr};
use vmedia_abi::{VM_ENCODER_CONFIG,VM_ENCODER_INPUT,VM_ENCODER_ABI_VERSION};
fn config()->VM_ENCODER_CONFIG{VM_ENCODER_CONFIG{Version:VM_ENCODER_ABI_VERSION,Size:56,SessionToken:7,Width:64,Height:48,YStride:64,UVStride:64,UVOffset:3072,FrameRateNum:30,FrameRateDen:1,Bitrate:2_000_000,GopFrames:60,Flags:0,Reserved0:0}}
fn frame(token:u32,id:u32)->VM_ENCODER_INPUT{VM_ENCODER_INPUT{Version:VM_ENCODER_ABI_VERSION,Size:56,SessionToken:token,BufferId:id,DataSize:4608,Flags:0,Timestamp:id as u64,YOffset:0,UVOffset:3072,YStride:64,UVStride:64,Reserved0:0,Reserved1:0}}
fn configure_queues(s:&mut EncoderSlot,input_count:u32)->EncoderPoolRanges{s.set_negotiated_formats(64,4608,65536).unwrap();let mut ranges=EncoderPoolRanges::new(256*1024);let mut off=0u64;for i in 0..input_count{ranges.insert(i,0,i as u64,off,8192,(i as u32)*8192,8192).unwrap();off+=8192;}for i in 0..2{ranges.insert(i,1,i as u64,off,65536,(i as u32)*65536,65536).unwrap();off+=65536;}s.configure_queues(EncoderQueueConfig{input_type:V4L2_ENCODER_OUTPUT_MPLANE,output_type:V4L2_ENCODER_CAPTURE_MPLANE,input_count,output_count:2,input_sizeimage:4608,output_sizeimage:65536,streamon_mask:2},&ranges).unwrap();ranges}
#[test]fn configure_queue_complete_and_drain(){let mut s=EncoderSlot::new(2);assert_eq!(s.configure(&config()).unwrap().total,4608);configure_queues(&mut s,2);assert_eq!(s.negotiated_config().YStride,64);assert_eq!(s.negotiated_config().UVStride,64);assert_eq!(s.negotiated_config().UVOffset,3072);let f=frame(7,11);assert_eq!((f.YOffset,f.UVOffset,f.YStride,f.UVStride),(0,s.negotiated_config().UVOffset,s.negotiated_config().YStride,s.negotiated_config().UVStride));assert_eq!(s.queue_input(&f,4608),Ok(11));assert_eq!(s.input_slot(11),Some(0));assert_eq!(s.queue_input(&frame(7,22),4608),Ok(22));assert_eq!(s.input_slot(22),Some(1));assert_eq!(s.queue_input(&frame(7,33),4608),Err(StateErr::QueueFull));assert_eq!(s.input_done(11),Ok(()));assert_eq!(s.queue_input(&frame(7,33),4608),Ok(33));s.begin_drain().unwrap();assert_eq!(s.begin_drain(),Err(StateErr::AlreadyDraining));assert_eq!(s.queue_input(&frame(7,4),4608),Err(StateErr::Draining));assert!(s.counters().drain_pending);s.complete_drain().unwrap();assert!(!s.counters().drain_pending);assert_eq!(s.complete_drain(),Err(StateErr::DrainNotPending));assert!(s.is_drained());assert_eq!(s.begin_drain(),Err(StateErr::AlreadyDraining));assert_eq!(s.queue_input(&frame(7,4),4608),Err(StateErr::Draining));}
#[test]fn empty_drain_is_one_shot_and_cancel_is_recoverable(){let mut s=EncoderSlot::new(2);s.configure(&config()).unwrap();assert_eq!(s.begin_drain(),Err(StateErr::QueueConfig));configure_queues(&mut s,2);s.begin_drain().unwrap();assert!(s.empty_drain_pending());s.cancel_drain();assert!(!s.empty_drain_pending());assert!(!s.counters().drain_pending);s.begin_drain().unwrap();s.complete_drain().unwrap();assert!(s.is_drained());assert!(!s.empty_drain_pending());s.cancel_drain();assert!(s.is_drained());assert_eq!(s.begin_drain(),Err(StateErr::AlreadyDraining));}
#[test]fn flush_replaces_token_and_clears_state(){let mut s=EncoderSlot::new(2);s.configure(&config()).unwrap();configure_queues(&mut s,2);s.queue_input(&frame(7,1),4608).unwrap();assert_eq!(s.flush(8),Ok(()));assert_eq!(s.token(),8);assert_eq!(s.counters().accepted_inputs,0);assert_eq!(s.queue_input(&frame(7,2),4608),Err(StateErr::BadRequest(EncoderRequestError::SessionToken)));configure_queues(&mut s,2);assert_eq!(s.queue_input(&frame(8,2),4608),Ok(2));assert_eq!(s.input_done(1),Err(StateErr::UnknownInputId));assert_eq!(s.input_done(2),Ok(()));}
#[test]fn cannot_flush_with_zero_or_same_generation(){let mut s=EncoderSlot::new(2);s.configure(&config()).unwrap();assert_eq!(s.flush(0),Err(StateErr::BadRequest(EncoderRequestError::SessionToken)));assert_eq!(s.flush(7),Err(StateErr::BadRequest(EncoderRequestError::SessionToken)));}
#[test]fn packet_completion_is_independent_of_input_done(){let mut s=EncoderSlot::new(2);s.configure(&config()).unwrap();configure_queues(&mut s,2);s.queue_input(&frame(7,41),4608).unwrap();s.packet_done().unwrap();assert_eq!(s.counters().accepted_inputs,1);assert_eq!(s.counters().completed_inputs,0);assert_eq!(s.counters().completed_packets,1);}
#[test]fn input_done_is_matched_by_buffer_id(){let mut s=EncoderSlot::new(1);s.configure(&config()).unwrap();configure_queues(&mut s,2);s.queue_input(&frame(7,99),4608).unwrap();assert_eq!(s.input_done(100),Err(StateErr::UnknownInputId));assert_eq!(s.input_done(99),Ok(()));assert_eq!(s.input_done(99),Err(StateErr::UnknownInputId));}
#[test]fn config_is_required_and_only_accepted_once(){let mut s=EncoderSlot::new(1);assert_eq!(s.queue_input(&frame(7,1),4608),Err(StateErr::NotConfigured));s.configure(&config()).unwrap();assert_eq!(s.configure(&config()),Err(StateErr::AlreadyConfigured));}
#[test]fn zero_config_token_is_rejected(){let mut s=EncoderSlot::new(1);let mut c=config();c.SessionToken=0;assert_eq!(s.configure(&c),Err(StateErr::BadRequest(EncoderRequestError::SessionToken)));}
#[test]fn capacity_is_bounded_by_fixed_slot_count(){let mut s=EncoderSlot::new(9);assert_eq!(s.configure(&config()),Err(StateErr::InvalidCapacity));}
#[test]fn negotiated_formats_are_required_and_size_checked(){let mut s=EncoderSlot::new(4);s.configure(&config()).unwrap();assert_eq!(s.configure_queues(EncoderQueueConfig{input_type:V4L2_ENCODER_OUTPUT_MPLANE,output_type:V4L2_ENCODER_CAPTURE_MPLANE,input_count:2,output_count:2,input_sizeimage:4608,output_sizeimage:65536,streamon_mask:2},&EncoderPoolRanges::new(262144)),Err(StateErr::QueueConfig));assert_eq!(s.set_negotiated_formats(32,4608,65536),Err(StateErr::QueueConfig));assert_eq!(s.set_negotiated_formats(64,4000,65536),Err(StateErr::QueueConfig));assert_eq!(s.set_negotiated_formats(64,4608,65536),Ok(()));}
#[test]fn negotiated_stride_requires_sufficient_size_and_failure_is_atomic(){let mut s=EncoderSlot::new(4);s.configure(&config()).unwrap();assert_eq!(s.set_negotiated_formats(128,4608,65536),Err(StateErr::QueueConfig));assert_eq!(s.negotiated_config().YStride,64);assert_eq!(s.negotiated_config().UVOffset,3072);assert_eq!(s.negotiated_sizes(),None);assert_eq!(s.set_negotiated_formats(128,9216,65536),Ok(()));assert_eq!(s.negotiated_config().UVOffset,6144);assert_eq!(s.layout().total,9216);}
#[test]fn queue_input_requires_encoder_v4l2_queue_negotiation(){let mut s=EncoderSlot::new(4);s.configure(&config()).unwrap();assert_eq!(s.queue_input(&frame(7,1),4608),Err(StateErr::QueueConfig));let ranges=configure_queues(&mut s,2);assert_eq!(ranges.count_kind(0),2);assert_eq!(ranges.count_kind(1),2);assert_eq!(s.queue_input(&frame(7,1),4608),Ok(1));assert_eq!(s.mark_input_streaming(),Ok(()));assert_eq!(s.queue_config().unwrap().streamon_mask,3);assert_eq!(s.mark_input_streaming(),Err(StateErr::AlreadyConfigured));}
#[test]fn encoder_queue_contract_rejects_wrong_direction_or_missing_buffers(){let mut s=EncoderSlot::new(4);s.configure(&config()).unwrap();s.set_negotiated_formats(64,4608,65536).unwrap();let mut ranges=EncoderPoolRanges::new(256*1024);for i in 0..2{ranges.insert(i,0,i as u64,i as u64*8192,8192,i*8192,8192).unwrap();}for i in 0..2{ranges.insert(i,1,i as u64+10,16384+i as u64*65536,65536,i*65536,65536).unwrap();}let mut q=EncoderQueueConfig{input_type:V4L2_ENCODER_CAPTURE_MPLANE,output_type:V4L2_ENCODER_OUTPUT_MPLANE,input_count:2,output_count:2,input_sizeimage:4608,output_sizeimage:65536,streamon_mask:2};assert_eq!(s.configure_queues(q,&ranges),Err(StateErr::QueueConfig));let mut s=EncoderSlot::new(4);s.configure(&config()).unwrap();s.set_negotiated_formats(64,4608,65536).unwrap();q.input_type=V4L2_ENCODER_OUTPUT_MPLANE;q.output_type=V4L2_ENCODER_CAPTURE_MPLANE;q.streamon_mask=1;assert_eq!(s.configure_queues(q,&ranges),Err(StateErr::QueueConfig));}
#[test]fn duplicate_buffer_id_is_rejected_until_completion(){let mut s=EncoderSlot::new(2);s.configure(&config()).unwrap();configure_queues(&mut s,2);s.queue_input(&frame(7,55),4608).unwrap();assert_eq!(s.queue_input(&frame(7,55),4608),Err(StateErr::DuplicateInputId));s.input_done(55).unwrap();assert_eq!(s.queue_input(&frame(7,55),4608),Ok(55));}
#[test]fn encoder_owner_has_independent_generation(){let mut e=EncoderOwner::empty();assert!(!e.open);assert_eq!(e.install(12,7),Ok(()));assert_eq!(e.install(13,8),Err(StateErr::AlreadyConfigured));assert!(!e.owns(8));assert!(e.owns(7));assert!(!e.clear(8));assert!(e.owns(7));assert!(e.clear(7));assert_eq!(e,EncoderOwner::empty());}
#[test]fn encoder_file_identity_is_bound_once_and_retired_with_token(){let mut e=EncoderOwner::empty();assert!(!e.bind_file(7,100));e.install(12,7).unwrap();assert!(!e.bind_file(8,100));assert!(!e.bind_file(7,0));assert!(e.bind_file(7,100));assert!(!e.bind_file(7,200));assert!(e.owns_file(100));assert!(!e.owns_file(200));assert!(!e.owns_file(0));assert!(e.clear(7));assert!(!e.owns_file(100));e.install(13,8).unwrap();assert!(e.bind_file(8,200));assert!(!e.owns_file(100));assert!(e.owns_file(200));assert!(!e.clear(7));assert!(e.owns_file(200));}
#[test]fn pool_ranges_are_bounded_nonoverlapping_and_reusable(){let mut p=EncoderPoolRanges::new(8192);assert_eq!(p.insert(0,0,100,0,4096,0,4096),Ok(()));assert_eq!(p.insert(1,1,200,4096,4096,4096,4096),Ok(()));assert_eq!(p.insert(2,1,300,2048,1024,8192,1024),Err(PoolRangeError::Overlap));assert_eq!(p.insert(2,1,300,8192,1,0,1),Err(PoolRangeError::OutOfPool));assert_eq!(p.len(),2);let old=p.remove(0,0).unwrap();assert_eq!(old.offset,0);assert_eq!(p.insert(2,0,300,0,1024,0,1024),Ok(()));assert_eq!(p.remove(9,0),Err(PoolRangeError::UnknownRange));}
#[test]fn one_pending_packet_is_preserved_until_consumed(){let mut s=EncoderSlot::new(2);s.configure(&config()).unwrap();let p=EncoderPendingPacket{index:1,bytesused:900,timestamp_us:1234,timestamp_valid:true,keyframe:true,last:false};assert_eq!(s.set_pending_packet(p),Ok(()));assert_eq!(s.set_pending_packet(p),Err(StateErr::PacketPending));assert_eq!(s.pending_packet(),Some(p));assert!(!s.clear_pending_packet(0));assert!(s.clear_pending_packet(1));assert_eq!(s.pending_packet(),None);}
#[test]fn flush_clears_pending_packet(){let mut s=EncoderSlot::new(2);s.configure(&config()).unwrap();let p=EncoderPendingPacket{index:1,bytesused:10,timestamp_us:0,timestamp_valid:true,keyframe:false,last:false};s.set_pending_packet(p).unwrap();s.flush(8).unwrap();assert_eq!(s.pending_packet(),None);}
#[test]fn pool_ranges_reject_overflow_zero_length_and_capacity_exhaustion(){let mut p=EncoderPoolRanges::new(u64::MAX);assert_eq!(p.insert(0,0,0,0,0,0,0),Err(PoolRangeError::ZeroLength));assert_eq!(p.insert(0,0,0,u64::MAX,1,0,1),Err(PoolRangeError::Overflow));let mut p=EncoderPoolRanges::new(64*(MAX_ENCODER_POOL_RANGES as u64+1));for i in 0..MAX_ENCODER_POOL_RANGES{assert_eq!(p.insert(i as u32,0,i as u64*64,i as u64*64,64,(i as u32)*64,64),Ok(()));}assert_eq!(p.insert(999,0,0,2560,64,0,64),Err(PoolRangeError::Full));}
